```typescript
function setupNotificationListener(userId: string) {
  const subscription = supabase
    .from(`notifications:user_id=eq.${userId}`)
    .on('INSERT', (payload) => {
      // 새 알림 처리
      showNotification(payload.new);
    })
    .subscribe();

  return () => {
    subscription.unsubscribe();
  };
}
```
