function usePermissions(resourceType: string, resourceId: string) {
  const { data } = useQuery(
    ['permissions', resourceType, resourceId],
    () => checkPermissions(resourceType, resourceId)
  );

  return {
    canView: data?.canView ?? false,
    canEdit: data?.canEdit ?? false,
    canDelete: data?.canDelete ?? false
  };
}
```
